pub fn slugify(input: &str) -> String {
    input
        .chars()
        .map(|c| if c.is_ascii_alphanumeric() { c.to_ascii_lowercase() } else { '-' })
        .collect::<String>()
        .trim_matches('-')
        .to_string()
}

pub fn slug_words(input: &str) -> Vec<String> {
    slugify(input)
        .split('-')
        .filter(|segment| !segment.is_empty())
        .map(|segment| segment.to_string())
        .collect()
}

pub fn is_valid_slug(input: &str) -> bool {
    !input.is_empty() && input == slugify(input)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lowercases_and_replaces_spaces() {
        assert_eq!(slugify("Hello World"), "hello-world");
    }

    #[test]
    fn slug_words_splits_on_hyphens() {
        assert_eq!(slug_words("Hello World"), vec!["hello", "world"]);
    }

    #[test]
    fn slug_words_removes_empty_segments() {
        assert_eq!(slug_words("Hello   World!!"), vec!["hello", "world"]);
    }

    #[test]
    fn slug_words_empty_input() {
        assert_eq!(slug_words(""), Vec::<String>::new());
    }

    #[test]
    fn is_valid_slug_accepts_already_slugified_input() {
        assert!(is_valid_slug("hello-world"));
    }

    #[test]
    fn is_valid_slug_rejects_unslugified_input() {
        assert!(!is_valid_slug("Hello World"));
    }

    #[test]
    fn is_valid_slug_rejects_empty_input() {
        assert!(!is_valid_slug(""));
    }
}

